def load() -> pd.DataFrame:
    import pandas as pd
    # Try common encodings for NOAA/legacy CSV exports
    for enc in ['cp1252', 'latin1', 'utf-8']:
        try:
            return pd.read_csv('data/wildfire/input/noaa_wildfires_variabledescrip.csv', encoding=enc)
        except UnicodeDecodeError:
            continue
    # Fallback: replace undecodable bytes
    return pd.read_csv('data/wildfire/input/noaa_wildfires_variabledescrip.csv', encoding='utf-8', encoding_errors='replace')

def load() -> pd.DataFrame:
